/**
* @brief Ark RTOS 应用层基础类型定义
* @details 此文件属于App SDK，仅包含基础类型定义，
*          不依赖任何MCU头文件或内核内部头文件。
*          应用程序只需包含 arkrtos.h 即可使用所有OS接口。
*/

#ifndef __ARKRTOS_TYPES_H__
#define __ARKRTOS_TYPES_H__
/* Build configuration generated by Kconfig (tools/kconfig/genconfig.py).
 * This is the lowest-level header every kernel and SDK translation unit
 * reaches, so the whole product sees one set of values.  Every macro in
 * the generated file is #ifndef-guarded, so a -D on the compiler command
 * line still wins. */
#include <arkrtos_autoconf.h>

/* On LP64 targets (e.g. LoongArch64) `long` is 64 bits, so `uint32` cannot be
 * defined in terms of it: every kernel struct, trap frame slot and MMIO
 * access assumes four bytes. `unsigned int` is 32 bits on every supported
 * toolchain (ARM AC5/AC6, RISC-V, LoongArch), so it is used only where a
 * 64-bit long would otherwise leak into the type. 32-bit targets keep the
 * historical definition so their object code stays bit-identical. */
#if defined(__LP64__) || defined(_LP64) || \
    (defined(__SIZEOF_LONG__) && (__SIZEOF_LONG__ > 4))
typedef unsigned int   uint32;
typedef signed   int   int32;
#else
typedef unsigned long  uint32;
typedef signed   long  int32;
#endif
typedef unsigned short uint16;
typedef signed   short int16;
typedef unsigned char  uint8;
typedef signed   char  int8;



/* Toolchain-independent weak-symbol attribute (AC5 vs AC6/GCC/Clang). */
#if defined(__CC_ARM)
#define ARKRTOS_WEAK __weak
#else
#define ARKRTOS_WEAK __attribute__((weak))
#endif

#endif
